FACTS. treeKeys in check-cache.mjs builds the cache key from a git tree of the tracked changes plus the untracked files, excluding only the scratch folder. A run appends docs/specs/<plan>-decisions.md after a check passes, either untracked or tracked and modified, so the tree key changes and the recorded pass misses. The fix leaves plan decisions files (docs/specs/*-decisions.md) out of the key for both the untracked and the tracked copy.
FAIL: the answer blames the cache file, the SUMMARY parsing, the query command or the clean-summary pattern, or only handles the untracked copy of the file.
PASS: the answer finds that the key is computed over every changed or untracked file including the decisions file written after the pass and excludes the decisions files from the key (the tracked copy too).
Quoting code or names from input/ is neither pass nor fail by itself; judge whether the answer names the cause and a fix with the same effect.
Reference fix, the real commit 1e21c4a5:
diff --git a/lib/check-cache.mjs b/lib/check-cache.mjs
index 363fb56d..607ad7ca 100644
--- a/lib/check-cache.mjs
+++ b/lib/check-cache.mjs
@@ -10,6 +10,7 @@ export const SLOW_GATE_MS = 60000;
 export const BRANCH_REVIEW_KEY = 'review-branch';

 const CACHE_FILE = 'check-cache.json';
+const DECISIONS_FILE = /^docs\/specs\/[^/]+-decisions\.md$/;
 const SUMMARY_LINE = /^SUMMARY [^\r\n]*/gm;
 export const CLEAN_SUMMARY = / FAIL=0 WARN=0 UNRUN=0\b/;

@@ -30,8 +31,10 @@ function treeKeys(root) {
     const env = { ...process.env, GIT_INDEX_FILE: index };
     git(['add', '-u'], env);
     const untracked = git(['ls-files', '--others', '--exclude-standard', '-z']).split('\0')
-      .filter((file) => file !== '' && file !== SCRATCH_FOLDER && !file.startsWith(`${SCRATCH_FOLDER}/`));
+      .filter((file) => file !== '' && file !== SCRATCH_FOLDER && !file.startsWith(`${SCRATCH_FOLDER}/`) && !DECISIONS_FILE.test(file));
     if (untracked.length > 0) git(['add', '--pathspec-from-file=-', '--pathspec-file-nul'], { ...env, GIT_LITERAL_PATHSPECS: '1' }, untracked.join('\0'));
+    // why: the run appends its plan decisions file after a pass, so a tracked copy must not move the key either.
+    git(['rm', '--cached', '-q', '--ignore-unmatch', '--', ':(glob)docs/specs/*-decisions.md'], env);
     const tree = git(['write-tree'], env).trim();
     git(['rm', '--cached', '-q', '--ignore-unmatch', '--', 'CHANGELOG.md'], env);
     return { tree, code: git(['write-tree'], env).trim() };
